components.css:
.ds-btn-primary {
  font-family: var(--font-inter), Inter, system-ui, sans-serif; font-size: 15px; font-weight: 500;
  color: var(--ds-on-ink); background: var(--ds-ink);
  border: 1px solid transparent; border-radius: var(--ds-r-ctl, 6px);
  height: 52px; padding: 0 28px; cursor: pointer;
  transition: background-color 160ms cubic-bezier(0.2, 0.7, 0.2, 1), transform 160ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.ds-btn-primary:hover {
  background: color-mix(in srgb, var(--ds-ink) 90%, transparent); transform: translateY(-1px);
}
.ds-btn-primary:focus-visible { outline: 2px solid var(--ds-acc); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  .ds-btn-primary { transition: none; }
  .ds-btn-primary:hover { transform: none; }
}

.ds-btn-secondary {
  font-family: var(--font-inter), Inter, system-ui, sans-serif; font-size: 15px; font-weight: 500;
  color: var(--ds-fg); background: transparent;
  border: 1px solid var(--ds-ink); border-radius: var(--ds-r-ctl, 6px);
  height: 52px; padding: 0 26px; cursor: pointer;
  transition: background-color 160ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.ds-btn-secondary:hover { background: var(--ds-panel); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--ds-acc); outline-offset: 2px; }

.ds-nav { display: flex; gap: 32px; font-family: var(--font-inter), Inter, system-ui, sans-serif; font-size: 14px; }
.ds-nav-link {
  color: var(--ds-fg); text-decoration: none; padding: 6px 0 0;
  border-bottom: 1px solid transparent; transition: border-color 160ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.ds-nav-link:hover { border-bottom-color: var(--ds-line); }
.ds-nav-link-active { font-weight: 500; border-bottom-color: var(--ds-fg); }

.ds-field { display: flex; flex-direction: column; gap: 8px; font-family: var(--font-inter), Inter, system-ui, sans-serif; }
.ds-field-label { font-size: 14px; font-weight: 500; color: var(--ds-fg); }
.ds-input {
  height: 46px; width: 100%; padding: 0 14px;
  font-family: var(--font-inter), Inter, system-ui, sans-serif; font-size: 15px; color: var(--ds-fg);
  background: var(--ds-panel); border: 1px solid var(--ds-line);
  border-radius: var(--ds-r-ctl, 6px);
  transition: border-color 160ms cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 160ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.ds-input::placeholder { color: color-mix(in srgb, var(--ds-muted) 80%, transparent); }
.ds-input:hover { border-color: var(--ds-muted); }
.ds-input:focus { outline: none; border-color: var(--ds-ink); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ds-ink) 10%, transparent); }
.ds-field-error { font-size: 13px; color: var(--ds-err); }

.ds-notice {
  font-family: var(--font-inter), Inter, system-ui, sans-serif; font-size: 14px; line-height: 1.55; color: var(--ds-fg);
  background: var(--ds-err-soft); border: 1px solid color-mix(in srgb, var(--ds-err) 25%, transparent);
  border-radius: var(--ds-r-ctl, 6px); padding: 12px 16px;
}
.ds-notice b { color: var(--ds-err); }

.ds-plan {
  background: var(--ds-panel); border: 1px solid var(--ds-line);
  border-radius: var(--ds-r-box, 10px);
  padding: 32px; font-family: var(--font-inter), Inter, system-ui, sans-serif;
}
.ds-plan-name {
  margin: 0; font-size: 11px; font-weight: 500; letter-spacing: 0.16em;
  text-transform: uppercase; color: var(--ds-muted);
}
.ds-plan-price {
  margin: 24px 0 0; font-size: 34px; font-weight: 600; line-height: 1;
  letter-spacing: -0.015em; font-variant-numeric: tabular-nums; color: var(--ds-fg);
}
.ds-plan-per { margin-left: 8px; font-size: 14px; font-weight: 400; color: var(--ds-muted); }
.ds-plan-vat { margin: 8px 0 0; font-size: 13px; color: var(--ds-muted); }

.ds-chips { display: flex; gap: 8px; font-family: var(--font-inter), Inter, system-ui, sans-serif; }
.ds-chip {
  display: inline-flex; align-items: center; gap: 10px;
  height: 44px; padding: 0 16px; font-size: 15px; color: var(--ds-fg);
  background: var(--ds-panel); border: 1px solid var(--ds-line);
  border-radius: var(--ds-r-ctl, 6px); transition: border-color 160ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.ds-chip:hover { border-color: var(--ds-muted); }
.ds-chip-on {
  background: color-mix(in srgb, var(--ds-plain-soft) 60%, transparent); border-color: var(--ds-ink); box-shadow: 0 0 0 1px var(--ds-ink);
}
.ds-dot {
  width: 16px; height: 16px; border-radius: 50%; border: 1px solid color-mix(in srgb, var(--ds-ink) 70%, transparent);
  display: inline-flex; align-items: center; justify-content: center;
}
.ds-chip-on .ds-dot::after {
  content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--ds-ink);
}
.ds-chip:focus-within { outline: 2px solid var(--ds-acc); outline-offset: 2px; }

.ds-shot {
  margin: 0; overflow: hidden; background: var(--ds-panel);
  border: 1px solid var(--ds-line); border-radius: var(--ds-r-box, 10px);
  box-shadow: 0 40px 80px -48px rgb(28 27 25 / 0.45);
}
.ds-shot-bar {
  display: flex; align-items: center; gap: 12px; height: 36px; padding: 0 14px;
  background: color-mix(in srgb, var(--ds-plain-soft) 60%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ds-line) 70%, transparent);
}
.ds-shot-bar span { width: 8px; height: 8px; border-radius: 50%; background: var(--ds-line); }
.ds-shot-bar code {
  font-family: var(--font-jetbrains-mono), ui-monospace, Menlo, monospace; font-size: 11.5px; color: var(--ds-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.ds-shot-body { aspect-ratio: 1040 / 640; background: var(--ds-page); }

.ds-faq { font-family: var(--font-inter), Inter, system-ui, sans-serif; border-bottom: 1px solid var(--ds-line); }
.ds-faq summary {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding: 22px 0; font-size: 17px; font-weight: 500; color: var(--ds-fg); cursor: pointer;
}
.ds-faq summary::-webkit-details-marker { display: none; }
.ds-faq summary::after {
  content: '+'; flex: none; width: 28px; height: 28px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 16px; font-weight: 400;
  border: 1px solid var(--ds-line); border-radius: var(--ds-r-ctl, 6px);
}
.ds-faq[open] summary::after { content: '\2212'; }
.ds-faq-a {
  margin: 0 0 24px; padding-right: 64px;
  font-size: 15px; line-height: 1.7; color: color-mix(in srgb, var(--ds-fg) 80%, transparent);
}
